 const roastNotes={'light-medium':'花果香明亮，帶柔和甜感',medium:'酸甜平衡，焦糖甜感','medium-dark':'可可堅果，口感醇厚'};
 const lineSpec=i=>i.kind==='treat'?esc(i.treat.spec):esc(S.variantLabel(i.variant))+(i.roast?' · '+esc(S.roastLabels[i.roast]):'')+(i.grind?' · '+esc(S.grindLabels[i.grind]):'');
 function treatCard(t){return `<article class="coffee-card"><a class="product-photo" href="treats.html"><img src="${esc(t.image)}" alt="${esc(t.name)}示意插圖" loading="lazy"><span class="roast-label">${esc(t.spec)}</span></a><div class="product-copy"><p class="product-origin">${esc(t.shelf)}</p><h3>${esc(t.name)}</h3><p class="product-description">${esc(t.description)}</p><div class="product-bottom"><p><strong>${money(t.price)}</strong><span>${t.stock?esc(t.spec):'已售完'}</span></p><a class="product-link" href="treats.html">查看點心 ↗</a></div></div></article>`}
 function coffeeCard(p,home=false){const v=p.variants[0];if(home)return `<article class="coffee-card" data-flavor-card="${p.flavor}" data-search="${esc([p.name,p.country,...p.flavors].join(' '))}"><a class="product-photo" href="${link(p)}">${img(p.gallery[0])}</a><div class="product-copy"><p class="product-origin">${esc(p.country)} / ${esc(p.region)}</p><h3>${esc(p.name)}</h3><p class="flavor-line">${esc(p.flavors.join(' / '))}</p><p class="product-description">${esc(p.description)}</p><div class="product-bottom"><p><strong>${money(v.price)}</strong><span>200g / 包</span></p><a class="product-link" href="${link(p)}">查看咖啡 ↗</a></div></div></article>`;
 const r=cardRoast(p),rp=p.roastProfiles?.[r]||{},en=window.CoffeeI18n.lang==='en',flavors=(en&&rp.flavorsEn?.length?rp.flavorsEn:rp.flavors?.length?rp.flavors:p.flavors),photo=rp.image?{...(p.gallery.find(i=>i.src===rp.image)||p.gallery[0]),src:rp.image}:p.gallery[0];
 return `<article class="catalog-card" data-card-id="${esc(p.id)}"><a class="catalog-photo" href="${link(p)}${r?'&roast='+encodeURIComponent(r):''}">${img(photo)}<div class="catalog-overlay"><p class="catalog-origin">${esc(p.country)} / ${esc(p.process)}</p><h2>${esc(p.name)}</h2><p class="catalog-flavors">${esc(flavors.join(' · '))}</p></div></a><div class="catalog-foot"><div class="card-roasts" role="group" aria-label="烘焙度">${shopRoasts.map(x=>`<button type="button" data-card-roast="${x}" aria-pressed="${x===r}">${esc(S.roastLabels[x])}</button>`).join('')}</div><strong>${money(v.price)}</strong></div></article>`}
 let catalogFilter={q:'',country:'all',sort:'featured'};
