 const cardRoasts={},cardRoast=p=>{if(!(p.id in cardRoasts)){const d=S.defaultRoast(p);cardRoasts[p.id]=shopRoasts.includes(d)?d:''}return cardRoasts[p.id]};
 function renderCatalog(){const s=view(),products=s.products.filter(p=>p.active);const countries=[...new Set(products.map(p=>p.country))];document.getElementById('store-main').innerHTML=`<div class="page-intro"><p class="section-kicker" data-content="shop.kicker">ROASTED COFFEE COLLECTION</p><h1 data-content="shop.title">選一款，喜歡的風味。</h1><p>${products.length} 款熟豆選品，從花果香到可可尾韻。<br>咖啡豆為 200g 一包，也有濾掛包與濾泡包，打開就能沖。</p></div><div class="catalog-toolbar"><label>搜尋咖啡<input id="catalog-search" type="search" placeholder="產區、名稱、風味" value="${esc(catalogFilter.q)}"></label><label>產區<select id="country-filter"><option value="all">全部產區</option>${countries.map(c=>`<option ${catalogFilter.country===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>排序<select id="catalog-sort"><option value="featured">精選順序</option><option value="price-asc">價格由低至高</option><option value="price-desc">價格由高至低</option><option value="fresh">烘焙日期由新至舊</option></select></label></div><p id="catalog-results" role="status"></p><div id="catalog-grid" class="catalog-grid"></div>`;
 document.getElementById('catalog-sort').value=catalogFilter.sort;
 const draw=()=>{let list=products.filter(p=>(catalogFilter.country==='all'||p.country===catalogFilter.country)&&([p.name,p.country,p.region,p.variety,p.process,...p.flavors].join(' ')+' '+window.CoffeeI18n.translate([p.name,p.country,p.region,p.variety,p.process,...p.flavors].join(' '))).toLowerCase().includes(catalogFilter.q.toLowerCase()));if(catalogFilter.sort.startsWith('price'))list.sort((a,b)=>(a.variants[0].price-b.variants[0].price)*(catalogFilter.sort==='price-asc'?1:-1));if(catalogFilter.sort==='fresh')list.sort((a,b)=>String(batchFor(b,s)?.roastDate).localeCompare(String(batchFor(a,s)?.roastDate)));document.getElementById('catalog-results').textContent=`找到 ${list.length} 款熟豆`;document.getElementById('catalog-grid').innerHTML=list.length?list.map(p=>coffeeCard(p)).join(''):'<div class="empty-panel">沒有符合條件的咖啡。請清除搜尋或調整篩選。</div>';document.querySelectorAll('#catalog-grid img').forEach(i=>{if(i.complete)markSquare(i)})};
 // 方形商品照（白底豆袋）在卡片中縮小並靠上，避免被下緣文字蓋住；滿版情境照維持裁切填滿。
 const markSquare=i=>{if(i.naturalWidth&&Math.abs(i.naturalWidth/i.naturalHeight-1)<.08)i.classList.add('is-square')};document.getElementById('catalog-grid').addEventListener('load',e=>{if(e.target.tagName==='IMG')markSquare(e.target)},true);
 document.getElementById('catalog-grid').addEventListener('click',e=>{const b=e.target.closest('[data-card-roast]');if(!b)return;const card=b.closest('[data-card-id]'),p=products.find(p=>p.id===card.dataset.cardId);if(!p)return;cardRoasts[p.id]=b.dataset.cardRoast;card.outerHTML=coffeeCard(p);document.querySelectorAll(`[data-card-id="${CSS.escape(p.id)}"] img`).forEach(i=>{if(i.complete)markSquare(i)});document.querySelector(`[data-card-id="${CSS.escape(p.id)}"] [data-card-roast="${b.dataset.cardRoast}"]`)?.focus()});
 [['catalog-search','q','input'],['country-filter','country','change'],['catalog-sort','sort','change']].forEach(([id,key,event])=>document.getElementById(id).addEventListener(event,e=>{catalogFilter[key]=e.target.value;draw()}));draw()}
 let selectedSku='',selectedGrind='whole',selectedRoast='',galleryIndex=0;
 const wantedFormat=new URLSearchParams(location.search).get('format');
 function renderProduct(){const s=view(),id=new URLSearchParams(location.search).get('id')||'yirgacheffe',p=s.products.find(p=>p.id===id);if(!p){document.getElementById('store-main').innerHTML='<div class="empty-panel"><h1>找不到這款咖啡</h1><a class="primary-button" href="shop.html">回到商品選購</a></div>';return}if(!p.variants.some(v=>v.sku===selectedSku))selectedSku=(p.variants.find(v=>S.formatOf(v)===wantedFormat)||p.variants[0]).sku;if(!shopRoasts.includes(selectedRoast)){const q=new URLSearchParams(location.search).get('roast'),d=S.defaultRoast(p);selectedRoast=shopRoasts.includes(q)?q:shopRoasts.includes(d)?d:'';galleryIndex=photoIndex(p,selectedRoast,selectedSku)}galleryIndex=Math.min(galleryIndex,p.gallery.length-1);const v=p.variants.find(v=>v.sku===selectedSku),bean=S.formatOf(v)==='bean',b=batchFor(p,s),ref=p.reference||{};const unit=x=>S.formatOf(x)==='bean'?`${x.grams}g`:`${x.count} 入`,sum=q=>bean?`${q} 包 × ${v.grams}g = ${q*v.grams}g`:`${q} 包 × ${v.count} 入 = ${q*v.count} 入`;document.title=p.name+'｜'+s.settings.shopName;document.getElementById('store-main').innerHTML=`<nav class="breadcrumbs"><a href="index.html">首頁</a> / <a href="shop.html">熟豆選購</a> / ${esc(p.name)}</nav><div class="product-layout"><div class="gallery"><button id="gallery-main" class="gallery-main is-magazine${isFormatPhoto(p,p.gallery[galleryIndex].src)?' is-full':''}" aria-label="放大商品圖片">${img(p.gallery[galleryIndex])}<span class="catalog-overlay"><span class="catalog-origin">${esc(p.country)} / ${esc(p.process)}</span><span class="catalog-name">${esc(p.name)}</span><span class="catalog-flavors" id="gallery-flavors">${esc(roastFlavors(p,selectedRoast).join(' · '))}</span></span></button><p class="gallery-caption" id="gallery-caption">${galleryIndex+1} / ${p.gallery.length} · ${esc(p.gallery[galleryIndex].label)}</p><div class="gallery-thumbs" role="group" aria-label="商品圖片">${p.gallery.map((i,n)=>`<button type="button" data-gallery="${n}" aria-label="第${n+1}張：${esc(i.label)}" aria-pressed="${n===galleryIndex}">${img(i)}</button>`).join('')}</div><p class="image-note">圖片為豆子、產區、包裝與沖煮情境示意，非實際批次或特定莊園實拍。</p></div><div class="product-detail"><p class="section-kicker">${esc(p.country)} / ${esc(p.process)} / 熟豆</p><h1>${esc(p.name)}</h1><p class="detail-price" id="detail-price">${money(v.price)} <small>每包</small></p><form id="add-cart-form"><fieldset class="roast-step"><legend><span class="step-badge">1</span>烘焙度</legend><div class="roast-options">${shopRoasts.map(r=>`<button type="button" data-roast="${r}" aria-pressed="${r===selectedRoast}"><strong>${esc(S.roastLabels[r])}</strong><span>${esc(roastNotes[r])}</span></button>`).join('')}</div><p class="muted">接單後依你選的焙度烘焙，約 3–7 天出貨。</p></fieldset><fieldset class="grind-step"><legend><span class="step-badge">2</span>選型態</legend><div class="variant-options">${p.variants.map(x=>`<button type="button" data-sku="${x.sku}" aria-pressed="${x.sku===selectedSku}"><strong>${esc(S.variantLabel(x))}</strong><span>${money(x.price)}${x.stock?'':' · <b class="sold-out">已售完</b>'}</span></button>`).join('')}</div></fieldset>${bean?`<fieldset class="grind-step"><legend><span class="step-badge">3</span>研磨方式</legend><div class="grind-options">${S.grinds.map(g=>`<button type="button" data-grind="${g}" aria-pressed="${g===selectedGrind}">${esc(S.grindLabels[g])}</button>`).join('')}</div><p class="muted">研磨後香氣散失較快，建議兩週內喝完；有磨豆機選原豆最新鮮。</p></fieldset>`:`<p class="format-note">${v.format==='drip'?'濾掛包：掛在杯緣，分 3–4 次注入約 150–180ml 熱水，不需要其他器材。':'濾泡包：像茶包一樣放進杯中，熱水浸泡 3–4 分鐘；也可以冷水冷藏 8 小時做冷泡。'}</p>`}<div class="quantity-line"><label for="product-quantity">購買包數</label><input type="number" id="product-quantity" value="1" min="1" max="${Math.min(99,v.stock)||1}" required><p id="weight-summary">${sum(1)}</p></div><button class="primary-button full-button" type="submit" ${!p.active||!v.stock?'disabled':''}>${!p.active?'此商品已下架':!v.stock?'此規格暫時售罄':'加入購物車'}</button></form></div></div><section class="product-section" id="brew-guide"><p class="section-kicker">BREW YOUR DAILY CUP</p><h2>手沖起始建議</h2><div class="brew-grid"><p>粉水比<strong>${esc(p.brew?.ratio||'1:15–1:16')}</strong></p><p>參考水溫<strong>${esc(p.brew?.temperature||'依口味調整')}</strong></p><p>研磨程度<strong>${esc(p.brew?.grind||'中細研磨')}</strong></p><p>可選規格<strong>${p.variants.length} 種</strong></p></div><p class="muted">${esc(p.brew?.note||'建議起始參數，可依口味調整。')} 取用後密封，置於陰涼乾燥處，避開高溫與日曬。賞味與保存期限應依實際包裝標示。</p></section><section class="product-section"><div class="section-heading"><h2>也許你也喜歡</h2><a href="shop.html" class="text-link">全部選品 ↗</a></div><div class="catalog-grid related-grid">${s.products.filter(x=>x.active&&x.id!==p.id).slice(0,3).map(x=>coffeeCard(x)).join('')}</div></section><dialog id="image-lightbox" class="image-lightbox"><button type="button" id="image-close" aria-label="關閉大圖">×</button>${img(p.gallery[galleryIndex])}<p>${esc(p.gallery[galleryIndex].label)} · 示意圖片</p></dialog>`;
 {const mi=document.querySelector('#gallery-main img');mi.addEventListener('load',()=>squareCheck(mi));if(mi.complete)squareCheck(mi)}document.querySelectorAll('[data-gallery]').forEach(button=>button.addEventListener('click',()=>{galleryIndex=Number(button.dataset.gallery);const i=p.gallery[galleryIndex];document.querySelector('#gallery-main img').src=i.src;document.getElementById('gallery-main').classList.toggle('is-full',isFormatPhoto(p,i.src));document.querySelector('#gallery-main img').alt=i.alt;document.getElementById('gallery-caption').textContent=`${galleryIndex+1} / ${p.gallery.length} · ${i.label}`;document.querySelectorAll('[data-gallery]').forEach(x=>x.setAttribute('aria-pressed',String(x===button)))}));
 document.querySelectorAll('[data-sku]').forEach(button=>button.addEventListener('click',()=>{selectedSku=button.dataset.sku;galleryIndex=photoIndex(p,selectedRoast,selectedSku);renderProduct();document.querySelector(`[data-sku="${selectedSku}"]`).focus({preventScroll:true})}));
 document.querySelectorAll('[data-roast]').forEach(button=>button.addEventListener('click',()=>{selectedRoast=button.dataset.roast;document.querySelectorAll('[data-roast]').forEach(x=>x.setAttribute('aria-pressed',String(x===button)));document.querySelector(`[data-gallery="${photoIndex(p,selectedRoast,selectedSku)}"]`)?.click();document.getElementById('gallery-flavors').textContent=roastFlavors(p,selectedRoast).join(' · ');}));
 document.querySelectorAll('[data-grind]').forEach(button=>button.addEventListener('click',()=>{selectedGrind=button.dataset.grind;document.querySelectorAll('[data-grind]').forEach(x=>x.setAttribute('aria-pressed',String(x===button)))}));
 document.getElementById('product-quantity').addEventListener('input',e=>{document.getElementById('weight-summary').textContent=sum(Number(e.target.value))});
 document.getElementById('add-cart-form').addEventListener('submit',event=>{event.preventDefault();if(!selectedRoast){toast('請先選擇烘焙度');document.querySelector('.roast-step')?.scrollIntoView({behavior:'smooth',block:'center'});return}act(()=>{S.addCart(p.id,selectedSku,Number(document.getElementById('product-quantity').value),bean?selectedGrind:undefined,selectedRoast);toast('已加入購物車，可前往購物車調整包數。')})});
 const box=document.getElementById('image-lightbox');document.getElementById('gallery-main').addEventListener('click',()=>{box.querySelector('img').src=p.gallery[galleryIndex].src;box.querySelector('img').alt=p.gallery[galleryIndex].alt;box.querySelector('p').textContent=p.gallery[galleryIndex].label+' · 示意圖片';box.showModal()});document.getElementById('image-close').addEventListener('click',()=>box.close());
 }
 function renderTreats(){const s=view(),list=s.treats.filter(t=>t.active);document.getElementById('store-main').innerHTML=`<div class="page-intro"><p class="section-kicker" data-content="treats.kicker">HANDMADE TREATS</p><h1 data-content="treats.title">配一口，剛剛好的甜。</h1><p data-content="treats.intro">手作小點，與咖啡最好的相遇。<br>點心為新鮮製作，下單後約 3–5 天出貨，請盡早享用。</p></div><div class="treat-grid">${list.map(t=>`<article class="treat-card"><img src="${esc(t.image)}" alt="${esc(t.name)}示意插圖" loading="lazy"><div class="treat-copy"><p class="section-kicker">${esc(t.spec)} · ${esc(t.shelf)}</p><p class="treat-temp is-${S.tempOf(t)}">${{frozen:'❄ 冷凍配送・另裝一箱寄出',ambient:'📦 常溫配送・可與咖啡同箱',either:'📦❄ 常溫冷凍皆可・自動選最省的寄法'}[S.tempOf(t)]}</p><h2>${esc(t.name)}</h2><p class="catalog-description">${esc(t.description)}</p><div class="catalog-price"><strong>${money(t.price)}</strong>${t.stock?'':'<small>已售完</small>'}</div><form class="treat-form" data-treat="${esc(t.id)}"><label>數量<input type="number" name="quantity" value="1" min="1" max="${Math.min(99,t.stock)||1}" required></label><button class="primary-button" type="submit" ${t.stock?'':'disabled'}>${t.stock?'加入購物車':'暫時售罄'}</button></form></div></article>`).join('')||'<div class="empty-panel">目前沒有上架的點心。</div>'}</div><p class="image-note" data-content="treats.note">點心圖片為示意插圖。點心屬易腐食品，不適用七天猶豫期；收到時若有破損請 3 日內聯繫我們。</p>`;
 document.querySelectorAll('[data-treat]').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();act(()=>{S.addTreat(form.dataset.treat,Number(form.quantity.value));toast('已加入購物車，可前往購物車調整數量。')})}))}
 let subChoice={planId:'regular',cycle:'1',roast:'any',grind:'whole',delivery:'711',fields:{}};
 // 月費訂購在後台開放後才顯示表單；?preview=測試碼 可在開放前測試（伺服器會驗證測試碼）
 const subPreview=()=>{const p=new URLSearchParams(location.search).get('preview');if(p){try{sessionStorage.setItem('encounter-sub-preview',p)}catch(_){}}try{return p||sessionStorage.getItem('encounter-sub-preview')||''}catch(_){return p||''}};
