 function renderCheckout(){const q=new URLSearchParams(location.search);if(q.get('order')&&q.get('t'))return renderOrderStatus(q.get('order'),q.get('t'));const backFromMap=takeStoreFromURL();const draft=backFromMap?readSession('encounter-checkout-draft'):null;if(draft){renderCheckout.delivery=draft.delivery||renderCheckout.delivery;renderCheckout.frozenDelivery=draft.frozenDelivery||renderCheckout.frozenDelivery;renderCheckout.payMethod='Credit'}const s=view(),c=S.cartDetails(s);const main=document.getElementById('store-main');const editing=new URLSearchParams(location.search).get('edit')==='1';if(!c.lines.length){main.innerHTML='<div class="empty-panel"><p class="section-kicker" data-content="checkout.empty.kicker">YOUR COFFEE BAG</p><h1 data-content="checkout.empty.title">購物車還沒有咖啡。</h1><p data-content="checkout.empty.copy">選一款喜歡的豆，加入購物車。</p><a class="primary-button" href="shop.html" data-content="checkout.empty.shop">探索 10 款熟豆 <span aria-hidden="true">→</span></a><a class="text-link" href="treats.html" data-content="checkout.empty.treats">看看點心 <span aria-hidden="true">↗</span></a></div>';if(!editing)return}let delivery=renderCheckout.delivery||'711',payMethod='Credit',frozenDelivery=renderCheckout.frozenDelivery||delivery;const frozenOnly=c.lines.length>0&&!c.hasAmbient;if(frozenOnly)delivery=frozenDelivery;const rates=s.settings.shippingRates;const lang=window.CoffeeI18n.lang,hasTreat=editing||c.lines.some(i=>i.kind==='treat'),hasFrozen=editing||c.hasFrozen;main.innerHTML=(c.lines.length?'':main.innerHTML)+`<div class="page-intro"><p class="section-kicker" data-content="checkout.kicker">YOUR COFFEE BAG</p><h1 data-content="checkout.title">把喜歡的風味，帶回日常。</h1><p data-content="checkout.intro">確認品項與配送方式，填好收件資料後前往綠界付款。</p></div><div class="checkout-layout"><div><div class="free-ship" id="free-ship" role="status"></div>${(()=>{const row=i=>`<article class="cart-line">${i.kind==='treat'?`<img src="${esc(i.treat.image)}" alt="${esc(i.treat.name)}示意插圖">`:img(i.product.gallery[0])}<div>${i.kind==='treat'?`<a href="treats.html"><h2>${esc(i.name)}</h2></a>`:`<a href="${link(i.product)}"><h2>${esc(i.name)}</h2></a>`}<p>${lineSpec(i)} · ${money(i.price)} / ${i.kind==='treat'?'份':'包'}</p><p class="muted">${i.kind==='treat'?esc(i.treat.shelf)+(S.tempOf(i.treat)==='either'?(lang==='en'?(i.frozen?' · Packed in the frozen box to save shipping':' · Packed with the room-temperature box'):(i.frozen?' · 常溫冷凍皆可，已併入冷凍箱':' · 常溫冷凍皆可，已併入常溫箱')):''):'批次 '+esc(i.product.batchId||'未排程')+` · 可售 ${i.stock} 包`}</p><label>${i.kind==='treat'?'數量':'包數'} <input type="number" min="1" max="${Math.min(99,i.stock)||1}" value="${i.quantity}" data-cart-quantity="${esc(i.key)}"></label><button class="text-link" type="button" data-remove="${esc(i.key)}">移除</button></div><strong>${money(i.lineTotal)}</strong></article>`;const amb=c.lines.filter(i=>!i.frozen),frz=c.lines.filter(i=>i.frozen),en=lang==='en',note=hasTreat?'<p class="format-note" data-content="checkout.treatNote">點心為新鮮製作，下單後約 3–5 天出貨，請盡早享用。</p>':'';if(!frz.length)return `<div class="cart-lines">${amb.map(row).join('')}</div>${note}`;const sum=a=>money(a.reduce((n,i)=>n+i.lineTotal,0));const head=(icon,title,sub,lines)=>`<div class="cart-group-head" data-no-translate><h3><span aria-hidden="true">${icon}</span> ${title}<small>${sub}</small></h3><span>${en?'Subtotal':'小計'} <strong>${sum(lines)}</strong></span></div>`;const ac=amb.some(i=>i.kind!=='treat'),at=amb.some(i=>i.kind==='treat'),ambSub=ac&&at?(en?'Coffee & room-temp desserts':'咖啡＋常溫甜點'):at?(en?'Room-temp desserts':'常溫甜點'):(en?'Coffee':'咖啡');return (amb.length?`<section class="cart-group cart-group-coffee">${head('📦',en?'Room temperature':'常溫寄送',ambSub,amb)}<div class="cart-lines">${amb.map(row).join('')}</div></section>`:'')+`<section class="cart-group cart-group-treat">${head('❄',en?'Frozen':'冷凍寄送',en?'Frozen desserts · separate parcel':'冷凍甜點・另裝一箱寄出',frz)}<div class="cart-lines">${frz.map(row).join('')}</div></section>`+note})()}<form id="checkout-form" class="customer-form"><h2 data-content="checkout.form.title">訂購資料</h2><p class="muted pay-mode-note" hidden>目前為綠界「測試環境」：不會真的扣款，請使用測試信用卡 4311-9522-2222-2222。</p><label><span data-content="checkout.form.name">姓名</span><input name="name" autocomplete="name" required maxlength="80"></label><label><span data-content="checkout.form.email">電子信箱</span><input type="email" name="email" autocomplete="email" required maxlength="150"></label><label><span data-content="checkout.form.phone">手機</span><input type="tel" name="phone" autocomplete="tel" required maxlength="30" placeholder="0912345678"></label><div class="${hasFrozen&&!frozenOnly?'ship-zone ship-zone-ambient':''}"><fieldset class="delivery-step" id="ambient-delivery"${frozenOnly?' hidden':''}>${hasFrozen?`<legend class="zone-head"><span class="zone-icon" aria-hidden="true">📦</span><span class="zone-title">${lang==='en'?'Room-temperature delivery':'常溫配送方式'}<small>${lang==='en'?'Coffee & room-temp items':'咖啡與常溫商品'}</small></span></legend>`:'<legend data-content="checkout.form.delivery">配送方式</legend>'}<div class="grind-options">${S.deliveries.map(d=>`<button type="button" data-delivery="${d}" aria-pressed="${d===delivery}"><span class="opt-name">${esc(S.deliveryLabels[d])}</span>${c.hasAmbient||!c.lines.length?`<span class="opt-fee">運費 ${money(rates[d])}</span>`:''}</button>`).join('')}</div></fieldset><label><span id="address-label">${delivery==='home'?'配送地址':'取貨門市'}</span><input name="address" required maxlength="300"></label><div class="store-pick" id="store-pick" hidden><button type="button" class="secondary-button" id="pick-store">選擇門市</button><span class="muted" data-content="checkout.form.storeHint">開啟超商官方門市地圖，選好後會自動帶回。</span></div></div>${hasFrozen?`<div class="ship-zone ship-zone-frozen"><fieldset class="delivery-step frozen-step"><legend class="zone-head"><span class="zone-icon" aria-hidden="true">❄</span><span class="zone-title">${lang==='en'?'Frozen delivery':'冷凍配送方式'}<small>${lang==='en'?'Frozen desserts · separate parcel':'冷凍甜點・另裝一箱寄出'}</small></span></legend><div class="grind-options">${S.frozenDeliveries.map(d=>`<button type="button" data-frozen-delivery="${d}" aria-pressed="${d===frozenDelivery}"><span class="opt-name">${esc(S.frozenDeliveryLabels[d])}</span><span class="opt-fee">運費 ${money(c.frozenRates[d])}</span></button>`).join('')}</div><p class="muted frozen-note" data-no-translate>${lang==='en'?`Frozen desserts ship <strong>frozen in a separate parcel</strong>${c.hasAmbient?', and you can choose a different way to ship them':''}. Free frozen shipping when frozen desserts total ${money(c.frozenFree)} or more. For store pickup, please choose a store that offers frozen pickup.`:`冷凍甜點需<strong>冷凍配送，另外裝一箱寄出</strong>${c.hasAmbient?'，寄送方式可以和常溫不同':''}。冷凍甜點滿 ${money(c.frozenFree)} 免冷凍運費。選超商取貨時，請選擇有提供冷凍取貨的門市。`}</p><div id="frozen-dest"></div></fieldset></div>`:''}<fieldset class="delivery-step"><legend data-content="checkout.form.pay">付款方式</legend><div class="grind-options">${[['Credit','信用卡','credit']].map(([m,n,k])=>`<button type="button" data-pay="${m}" aria-pressed="${m===payMethod}" data-content="checkout.pay.${k}">${n}</button>`).join('')}</div><p class="muted" id="pay-hint"></p></fieldset></form></div><aside class="order-summary"><span class="sum-kicker" aria-hidden="true">ORDER SUMMARY</span><h2 data-content="checkout.sum.title">訂單明細</h2><p><span data-content="checkout.sum.count">商品包數</span><strong>${c.count} 包</strong></p><p><span data-content="checkout.sum.subtotal">商品小計</span><strong>${money(c.subtotal)}</strong></p><p class="sum-fee sum-ambient"${c.hasAmbient||!c.lines.length?'':' hidden'}><span>${hasFrozen?'常溫運費':'運費'} · <span id="delivery-name">${esc(S.deliveryLabels[delivery])}</span></span><strong id="shipping-fee">${money(c.coffeeShipping)}</strong></p>${hasFrozen?`<p class="sum-fee sum-frozen"><span>冷凍運費 · <span id="frozen-delivery-name">${esc(S.frozenDeliveryLabels[frozenDelivery])}</span></span><strong id="frozen-fee">${money(c.frozenShipping)}</strong></p>`:''}<p class="summary-total"><span data-content="checkout.sum.total">應付總額</span><strong id="summary-total">${money(c.total)}</strong></p><details class="sum-ship-info"><summary>${lang==='en'?'Shipping & free-shipping details':'運費與免運說明'}</summary><small data-no-translate>${lang==='en'?`Room-temperature items (coffee and room-temp desserts) ship free over ${money(s.settings.freeShipping)}; otherwise 7-ELEVEN ${money(rates['711'])}, FamilyMart ${money(rates.family)}, home delivery ${money(rates.home)}. Frozen desserts are not counted toward free shipping.${hasFrozen?` Frozen desserts ship separately (7-11 frozen ${money(c.frozenRates['711'])}, FamilyMart frozen ${money(c.frozenRates.family)}, frozen home delivery ${money(c.frozenRates.home)}), free over ${money(c.frozenFree)} of frozen desserts.`:''}`:`常溫商品（咖啡與常溫甜點）滿 ${money(s.settings.freeShipping)} 免運；未滿依配送方式收運費（7-ELEVEN ${money(rates['711'])}、全家 ${money(rates.family)}、宅配 ${money(rates.home)}）。冷凍甜點不計入免運金額。${hasFrozen?`冷凍甜點另裝一箱寄出，冷凍運費依冷凍配送方式（7-11 冷凍 ${money(c.frozenRates['711'])}、全家冷凍 ${money(c.frozenRates.family)}、黑貓冷凍宅配 ${money(c.frozenRates.home)}），冷凍甜點滿 ${money(c.frozenFree)} 免冷凍運費。`:''}`}</small></details>${c.lines.some(i=>i.kind!=='treat')?`<div class="fresh-roast-note" data-no-translate>${lang==='en'?'<strong class="frn-title"><span aria-hidden="true">☕</span> Roasted fresh after you order</strong><p>Every bag is roasted only after you order, so it arrives at its freshest.</p><p class="frn-rule">Once your order shows <strong>Roasting</strong>, it can no longer be cancelled.</p>':'<strong class="frn-title"><span aria-hidden="true">☕</span> 下單後才新鮮烘焙</strong><p>每一包咖啡都在你下單後才開始烘焙，送到手上時正是風味最好的時候。</p><p class="frn-rule">訂單進度顯示<strong>「烘焙中」</strong>後，就無法再取消訂單。</p>'}</div>`:''}</aside><div class="checkout-submit"><div class="gift-box"><label><span data-content="checkout.form.note">備註（選填）</span><textarea name="note" form="checkout-form" maxlength="200" placeholder="${lang==='en'?'e.g. Preferred delivery time, company tax ID…':'例如：希望收件時段、需要統一編號…'}"></textarea></label></div><button class="primary-button full-button" type="submit" form="checkout-form" data-content="checkout.form.submit">前往付款</button><p class="muted" data-content="checkout.form.secure">付款由綠界科技 ECPay 處理，本站不會經手你的卡號。</p><p class="muted"><a href="policy.html" target="_blank" rel="noopener" style="text-decoration:underline">${lang==='en'?'Payment, shipping & returns policy ↗':'付款、運費與退換貨說明 ↗'}</a></p></div></div>`;
 const syncShipping=()=>{const d=S.cartDetails(s,delivery,frozenDelivery),box=document.getElementById('free-ship');if(box){const en=window.CoffeeI18n.lang==='en';box.setAttribute('data-no-translate','');const both=d.hasAmbient&&d.hasFrozen;const bar=p=>{const left=p.need-p.have;return left>0?`<p>${en?`${p.en?p.en+': a':'A'}dd <strong>${money(left)}</strong> more for free ${p.frozen?'frozen ':''}shipping <span class="free-ship-note">(free over ${money(p.need)}${p.noteEn||''})</span>`:`${p.zh}再買 <strong>${money(left)}</strong>，即可享${p.frozen?'冷凍':''}免運<span class="free-ship-note">（${p.zh}滿 ${money(p.need)} 免運${p.noteZh||''}）</span>`}</p><span class="free-ship-bar"><span style="width:${Math.min(100,Math.round(p.have/p.need*100))}%"></span></span>`:`<p>${en?`✓ Free ${p.frozen?'frozen ':''}shipping unlocked${p.en?' for '+p.en.toLowerCase():''} (over ${money(p.need)})`:`✓ ${p.zh}已達 ${money(p.need)}，享${p.frozen?'冷凍':''}免運費`}</p>`};const parts=[];if(d.hasAmbient||!d.lines.length)parts.push({have:d.ambientSubtotal,need:s.settings.freeShipping,zh:both?'常溫商品':'',en:both?'Room-temperature items':'',noteZh:d.hasFrozen?'，冷凍甜點不計入':'',noteEn:d.hasFrozen?'; frozen desserts not counted':''});if(d.hasFrozen)parts.push({have:d.frozenSubtotal,need:d.frozenFree,zh:'冷凍甜點',en:'Frozen desserts',frozen:true});box.classList.toggle('is-free',parts.every(p=>p.have>=p.need));box.innerHTML=parts.map(p=>`<div class="free-ship-part${p.have>=p.need?' done':''}">${bar(p)}</div>`).join('')}document.getElementById('shipping-fee').textContent=money(d.coffeeShipping);const ff=document.getElementById('frozen-fee');if(ff)ff.textContent=money(d.frozenShipping);const fn=document.getElementById('frozen-delivery-name');if(fn)fn.textContent=S.frozenDeliveryLabels[frozenDelivery];document.getElementById('delivery-name').textContent=S.deliveryLabels[delivery];document.getElementById('address-label').textContent=delivery==='home'?'配送地址':'取貨門市';document.getElementById('summary-total').textContent=money(d.total);syncStore();syncFrozenDest()};
// 冷凍箱的目的地：超商取貨要選冷凍取貨門市（同一家超商就沿用同一間），宅配要填地址（常溫也宅配時沿用上方地址）
 function syncFrozenDest(){const box=document.getElementById('frozen-dest');if(!box)return;const en=window.CoffeeI18n.lang==='en',prev=box.querySelector('[name=frozenAddress]')?.value??renderCheckout.frozenAddress??'';if(frozenOnly||!c.hasFrozen){box.innerHTML='';return}if(frozenDelivery==='home'){box.innerHTML=delivery==='home'?`<p class="muted">${en?'The frozen parcel goes to the delivery address above.':'冷凍箱寄到上方的配送地址。'}</p>`:`<label><span>${en?'Frozen delivery address':'冷凍配送地址'}</span><input name="frozenAddress" required maxlength="300" autocomplete="street-address" value="${esc(prev)}"></label>`;const fa=box.querySelector('[name=frozenAddress]');if(fa)fa.addEventListener('input',()=>{renderCheckout.frozenAddress=fa.value});return}const st=pickedStores()[frozenDelivery],same=frozenDelivery===delivery;box.innerHTML=`<label><span>${en?'Frozen pickup store':'冷凍取貨門市'}</span><input readonly value="${st?esc(storeText(st)):''}" placeholder="${en?'Use the button below to choose a store':'請按下方「選擇冷凍取貨門市」'}" data-no-translate></label><div class="store-pick"><button type="button" class="secondary-button" id="pick-frozen-store">${st?(en?'Change frozen pickup store':'重新選擇冷凍取貨門市'):(en?'Choose frozen pickup store':'選擇冷凍取貨門市')}</button><span class="muted">${same?(en?'Same store as your room-temperature parcel; changing it changes both.':'和常溫同一間門市；重新選擇會一起更換。'):(en?'Opens the official store map and brings your choice back.':'開啟超商官方門市地圖，選好後會自動帶回。')}</span></div>`;document.getElementById('pick-frozen-store').addEventListener('click',()=>openMap(frozenDelivery,document.getElementById('pick-frozen-store')))}
 function syncStore(){const box=document.getElementById('store-pick'),input=document.querySelector('#checkout-form [name=address]');if(!box||!input)return;const cvs=delivery!=='home',st=pickedStores()[delivery];box.hidden=!cvs;input.readOnly=cvs;if(cvs){input.value=st?storeText(st):'';input.placeholder='請按下方「選擇門市」';document.getElementById('pick-store').textContent=st?'重新選擇門市':'選擇門市'}else{if(input.dataset.fromStore==='1')input.value='';input.placeholder=''}input.dataset.fromStore=cvs?'1':''}
 async function openMap(chain,b){const form=document.getElementById('checkout-form'),f=Object.fromEntries(new FormData(form));saveSession('encounter-checkout-draft',{name:f.name,email:f.email,phone:f.phone,note:f.note,payMethod,delivery,frozenDelivery,frozenAddress:f.frozenAddress});b.disabled=true;try{const {map}=await window.CoffeeCloud.paymentMode();window.CoffeeCloud.goPay({action:map.action,fields:{MerchantID:map.merchantId,LogisticsType:'CVS',LogisticsSubType:map.types[chain],IsCollection:'N',ServerReplyURL:map.replyURL,ExtraData:'checkout',Device:innerWidth<768?'1':'0'}})}catch(e){toast(e.message);b.disabled=false}}
 document.getElementById('pick-store').addEventListener('click',()=>openMap(delivery,document.getElementById('pick-store')));
 syncShipping();
 document.querySelectorAll('[data-frozen-delivery]').forEach(b=>b.addEventListener('click',()=>{frozenDelivery=renderCheckout.frozenDelivery=b.dataset.frozenDelivery;if(frozenOnly)delivery=renderCheckout.delivery=frozenDelivery;document.querySelectorAll('[data-frozen-delivery]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));syncShipping()}));
 document.querySelectorAll('[data-delivery]').forEach(b=>b.addEventListener('click',()=>{delivery=renderCheckout.delivery=b.dataset.delivery;document.querySelectorAll('[data-delivery]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));syncShipping()}));
 const payHints={Credit:'下一步在綠界頁面輸入卡號，付款完成後訂單立即成立。商品會為你保留 30 分鐘，逾時未付款訂單將自動取消。'};const syncPay=()=>{document.getElementById('pay-hint').textContent=payHints[payMethod]};syncPay();if(draft){if(draft.frozenAddress){renderCheckout.frozenAddress=draft.frozenAddress;syncFrozenDest()}['name','email','phone','note'].forEach(k=>{const el=document.getElementById('checkout-form').elements[k];if(el&&draft[k])el.value=draft[k]});sessionStorage.removeItem('encounter-checkout-draft')}document.querySelectorAll('[data-pay]').forEach(b=>b.addEventListener('click',()=>{payMethod=renderCheckout.payMethod=b.dataset.pay;document.querySelectorAll('[data-pay]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));syncPay()}));
 document.querySelectorAll('[data-cart-quantity]').forEach(el=>el.addEventListener('change',()=>act(()=>{S.setCart(el.dataset.cartQuantity,Number(el.value));renderCheckout()})));document.querySelectorAll('[data-remove]').forEach(el=>el.addEventListener('click',()=>act(()=>{S.setCart(el.dataset.remove,0);renderCheckout()})));
 document.getElementById('checkout-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.target,button=document.querySelector('[type=submit][form=checkout-form]');const f=Object.fromEntries(new FormData(form));const cart=S.state().cart.map(i=>i.kind==='treat'?{kind:'treat',treatId:i.treatId,quantity:i.quantity}:{productId:i.productId,sku:i.sku,quantity:i.quantity,grind:i.grind,roast:i.roast});const store=delivery==='home'?undefined:pickedStores()[delivery];if(delivery!=='home'&&!store){toast('請先選擇取貨門市');document.getElementById('pick-store').focus();return}const frozenSend=c.hasFrozen?{frozenDelivery}:{};if(c.hasFrozen&&!frozenOnly){if(frozenDelivery!=='home'){frozenSend.frozenStore=pickedStores()[frozenDelivery];if(!frozenSend.frozenStore){toast('請先選擇冷凍取貨門市');document.getElementById('pick-frozen-store')?.focus();return}}else if(delivery!=='home'){frozenSend.frozenAddress=String(f.frozenAddress||'').trim();if(!frozenSend.frozenAddress){toast('請填寫冷凍配送地址');form.querySelector('[name=frozenAddress]')?.focus();return}}}if(delivery!=='home'||frozenSend.frozenStore){const problem=pickupProblem(f);if(problem){toast(problem);form.querySelector(problem.includes('手機')?'[name=phone]':'[name=name]').focus();return}}button.disabled=true;button.dataset.label=button.textContent;button.textContent='建立訂單中…';try{const r=await window.CoffeeCloud.checkout({cart,customer:{name:f.name,email:f.email,phone:f.phone,address:f.address},delivery,payMethod,store,note:f.note,...frozenSend});try{localStorage.setItem('encounter-last-order',JSON.stringify({id:r.orderId,token:r.token}))}catch(_){}main.innerHTML=`<div class="empty-panel"><p class="section-kicker">ORDER ${esc(r.orderId)}</p><h1>正在前往綠界付款頁面…</h1><p>訂單已建立，應付 ${money(r.total)}。</p></div>`;S.clearCart();window.CoffeeCloud.goPay(r.payment)}catch(e){toast(e.message);button.disabled=false;button.textContent=button.dataset.label||'前往付款'}});
 window.CoffeeCloud?.paymentMode().then(m=>{if(m.mode==='stage')document.querySelectorAll('.pay-mode-note').forEach(n=>n.hidden=false)}).catch(()=>{});
 }
 const readSession=k=>{try{return JSON.parse(sessionStorage.getItem(k)||'null')}catch(_){return null}},saveSession=(k,v)=>{try{sessionStorage.setItem(k,JSON.stringify(v))}catch(_){}};
 const pickedStores=()=>readSession('encounter-stores')||{};
 const storeText=st=>`${st.name}（店號 ${st.id}）${st.address}`;
 // 超商取貨：收件人要用證件上的真實姓名（2～5 個中文字或 4～10 個英文字母）、09 開頭 10 碼手機。規則與伺服器 logistics.js 相同
function pickupProblem(f){const n=String(f.name||'').trim(),p=String(f.phone||'').trim();if(!/^[一-鿿]{2,5}$/.test(n)&&!/^[A-Za-z]{4,10}$/.test(n))return '超商取貨的收件人姓名須為 2～5 個中文字或 4～10 個英文字母，不能有數字、空格或符號（取貨時會核對證件）';if(/(小姐|先生|太太|女士)$/.test(n))return '超商取貨須填證件上的真實姓名，不能用「小姐」「先生」等稱呼（取貨時會核對證件）';if(!/^09\d{8}$/.test(p))return '超商取貨的手機須為 09 開頭的 10 碼數字';return ''}
function takeStoreFromURL(){const q=new URLSearchParams(location.search),id=q.get('store');if(!id)return false;const type=q.get('storeType')||'',delivery=type.startsWith('UNIMART')?'711':type.startsWith('FAMI')?'family':'';if(delivery&&/^[A-Za-z0-9]{1,10}$/.test(id)){const all=pickedStores();all[delivery]={id,name:(q.get('storeName')||'').trim(),address:(q.get('storeAddr')||'').trim(),type};saveSession('encounter-stores',all)}history.replaceState(null,'',location.pathname+(window.CoffeeI18n.lang==='en'?'?lang=en':''));return !!delivery}
 const paymentNames={unpaid:'尚未付款',paid:'已付款',refund_pending:'待退款',refunded:'已退款'};
 // 查詢訂單：A 訂單編號＋手機（馬上看進度）、B 輸入 Email 寄送所有訂單的進度連結
 function renderLookup(){const main=document.getElementById('store-main');let last=null;try{last=JSON.parse(localStorage.getItem('encounter-last-order')||'null')}catch(_){}const q=new URLSearchParams(location.search);
  main.innerHTML=`<div class="lookup-page"><p class="section-kicker">YOUR ORDER</p><h1>查詢訂單</h1><p class="muted">用訂單編號和下單手機馬上查看進度；找不到訂單編號的話，輸入 Email，我們會把這個信箱的訂單連結寄給你。</p>${last?.id&&last?.token?`<p><a class="text-link" href="checkout.html?order=${encodeURIComponent(last.id)}&t=${encodeURIComponent(last.token)}"><span>查看這台裝置最近的訂單</span> <span data-no-translate>${esc(last.id)}</span> ↗</a></p>`:''}<div class="grind-options lookup-tabs"><button type="button" data-lookup="phone" aria-pressed="true">訂單編號＋手機</button><button type="button" data-lookup="email" aria-pressed="false">用 Email 寄送連結</button></div><form class="customer-form" id="lookup-phone"><label><span>訂單編號</span><input name="id" required maxlength="20" placeholder="EC20261116ABCDEF" autocomplete="off" autocapitalize="characters" spellcheck="false"></label><label><span>下單時填寫的手機</span><input type="tel" name="phone" required maxlength="30" placeholder="0912345678" autocomplete="tel"></label><p>訂單編號在訂單確認信或綠界付款通知信裡，以 EC 開頭。</p><button class="primary-button" type="submit">查詢進度</button></form><form class="customer-form" id="lookup-email" hidden><label><span>下單時填寫的電子信箱</span><input type="email" name="email" required maxlength="150" autocomplete="email"></label><p>寄出後約 1 分鐘內會收到，也請查看垃圾郵件匣。</p><button class="primary-button" type="submit">寄送訂單連結</button></form><p class="lookup-sent" role="status" hidden>如果這個信箱有訂單，我們已經把查詢連結寄過去了，請到信箱查看。</p></div>`;
  const forms={phone:document.getElementById('lookup-phone'),email:document.getElementById('lookup-email')},sent=main.querySelector('.lookup-sent');if(q.get('order'))forms.phone.id.value=q.get('order');
  main.querySelectorAll('[data-lookup]').forEach(b=>b.addEventListener('click',()=>{main.querySelectorAll('[data-lookup]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));Object.entries(forms).forEach(([k,f])=>f.hidden=k!==b.dataset.lookup);sent.hidden=true}));
  const busy=(form,on,label)=>{const b=form.querySelector('[type=submit]');b.disabled=on;if(on){b.dataset.label=b.textContent;b.textContent=label}else b.textContent=b.dataset.label||b.textContent};
  forms.phone.addEventListener('submit',async event=>{event.preventDefault();const f=Object.fromEntries(new FormData(forms.phone));busy(forms.phone,true,'查詢中…');try{const r=await window.CoffeeCloud.lookupOrder(f.id.trim(),f.phone);location.href=`checkout.html?order=${encodeURIComponent(r.orderId)}&t=${encodeURIComponent(r.token)}`}catch(e){toast(e.message);busy(forms.phone,false)}});
  forms.email.addEventListener('submit',async event=>{event.preventDefault();const f=Object.fromEntries(new FormData(forms.email));busy(forms.email,true,'寄送中…');try{await window.CoffeeCloud.emailOrders(f.email.trim());sent.hidden=false;forms.email.reset()}catch(e){toast(e.message)}finally{busy(forms.email,false)}})}
 // 已付款訂單的出貨進度：已付款 → 備貨中 → 已出貨 →（超商：已到店）→ 已取貨／已送達，並顯示寄件代碼或物流單號
 function orderProgress(o){const pickup=o.delivery!=='home',s=o.shipment||{},steps=['已付款','備貨中','已出貨',...(pickup?['已到店']:[]),pickup?'已取貨':'已送達'],last=steps.length-1;let at={new:0,confirmed:1,packing:1,shipped:2,completed:last}[o.status]??0;if(o.status==='shipped'&&pickup&&s.arrived)at=3;if(s.pickedUp)at=last;
  const texts=[['付款完成，謝謝你的訂購。','我們會依你選擇的焙度烘焙，約 3–7 天出貨；出貨時會再寄信通知你。'],['正在為你準備咖啡。','咖啡烘焙、包裝中，出貨時會再寄信通知你。'],['你的咖啡出發了。',pickup?'包裹送達門市後這裡會更新，請留意取貨通知。':'包裹已交給物流，請留意收件。'],...(pickup?[['包裹已送達門市。','請攜帶與收件人姓名相同的證件到門市取貨。']]:[]),['訂單已完成。','謝謝你的支持，祝你喝得開心。']][at];
  const code=s.code||o.tracking,tracking=code?`<p class="order-tracking"><span>${s.code?'寄件代碼':'物流單號'}</span> <strong data-no-translate>${esc(code)}</strong>${s.status?` · <span data-no-translate>${esc(s.status)}</span>`:''}${pickup&&o.storeName?`<br><span>取貨門市</span> <span data-no-translate>${esc(o.storeName)}</span>`:''}</p>`:'';
  return {title:texts[0],note:texts[1],html:`<ol class="order-progress">${steps.map((x,i)=>`<li class="${i<at?'done':i===at?'current':''}"><span>${x}</span></li>`).join('')}</ol>${tracking}`}}
 // 訂單商品：有冷凍點心時分成常溫／冷凍兩箱，各箱的運費列在該箱最底部；付款後每支咖啡豆顯示烘焙進度（準備中／烘焙中／烘焙完成），出貨後一律顯示烘焙完成
 const isFrozenLine=i=>i.frozen||/^❄/.test(i.name);
 // 運費列前的配送方式小標籤（純 CSS 色塊，不是超商官方商標）
 // 冷凍箱加 ❄ 與冰藍底線，例如「7-11 ❄」「全家 ❄」
 const shipIcon=(d,frozen)=>{const cold=frozen?' ship-frozen':'',snow=frozen?' ❄':'';return d==='711'?`<i class="ship-icon ship-711${cold}" aria-hidden="true" data-no-translate>7-11${snow}</i>`:d==='family'?`<i class="ship-icon ship-family${cold}" aria-hidden="true"><span>全家</span>${snow}</i>`:d==='home'?`<i class="ship-icon ship-home" aria-hidden="true">🚚${snow}</i>`:''};
 function statusItems(o){const names={preparing:'準備中',roasting:'烘焙中',roasted:'烘焙完成'},show=o.payment==='paid'&&o.status!=='cancelled',done=['shipped','completed'].includes(o.status);const badge=i=>{const k=done&&i.roast?'roasted':i.roast;return show&&names[k]?` <em class="roast-badge roast-${k}">${names[k]}</em>`:''};const li=i=>`<li><span>${esc(i.name)} × ${i.quantity}${badge(i)}</span><strong>${money(i.price*i.quantity)}</strong></li>`;const frz=o.items.filter(isFrozenLine);if(!frz.length&&!o.frozenShipping)return o.items.map(li).join('')+`<li><span>${shipIcon(o.delivery)}運費 · ${esc(o.deliveryLabel)}</span><strong>${money(o.shipping)}</strong></li>`;const amb=o.items.filter(i=>!isFrozenLine(i)),f=o.frozenShipping||0,fee=(label,n)=>`<li class="order-fee"><span>${label}</span><strong>${n?money(n):'<span>免運</span>'}</strong></li>`,head=(t,extra='')=>`<li class="order-ship-group"><span>${t}</span>${extra}</li>`;return (amb.length?head('📦 常溫配送')+amb.map(li).join('')+fee(`${shipIcon(o.delivery)}<span>常溫運費</span> · <span>${esc(o.deliveryLabel)}</span>`,o.shipping-f):'')+head('❄ 冷凍配送・另裝一箱寄出',(o.frozenStoreName?`<small><span>取貨門市</span> <span data-no-translate>${esc(o.frozenStoreName)}</span></small>`:'')+(o.frozenTracking?`<small><span>冷凍配送單號</span> <strong data-no-translate>${esc(o.frozenTracking)}</strong></small>`:''))+frz.map(li).join('')+fee(`${shipIcon(o.frozenDelivery||o.delivery,true)}<span>冷凍運費</span>${o.frozenDeliveryLabel?` · <span>${esc(o.frozenDeliveryLabel)}</span>`:''}`,f)}
 async function renderOrderStatus(id,token,tries=0){const main=document.getElementById('store-main');if(!tries)main.innerHTML='<div class="empty-panel"><p class="section-kicker">YOUR ORDER</p><h1>查詢訂單中…</h1></div>';let r;try{r=await window.CoffeeCloud.orderStatus(id,token)}catch(e){main.innerHTML=`<div class="empty-panel"><p class="section-kicker">YOUR ORDER</p><h1>找不到這筆訂單。</h1><p>${esc(e.message)}</p><a class="primary-button" href="orders.html?order=${encodeURIComponent(id)}">查詢訂單 →</a> <a class="text-link" href="shop.html">繼續選購 ↗</a></div>`;return}const o=r.order,paid=o.payment==='paid',cancelled=o.status==='cancelled',waiting=!paid&&!cancelled&&o.payment==='unpaid',progress=orderProgress(o);
  main.innerHTML=`<div class="empty-panel order-status"><p class="section-kicker">ORDER ${esc(o.id)}</p><h1>${paid?progress.title:cancelled?'這筆訂單已取消。':waiting?'尚未完成付款。':esc(paymentNames[o.payment]||o.payment)}</h1>${paid?progress.html:''}<p>${paid?progress.note:waiting?(tries<6?'如果剛在綠界完成付款，頁面會在幾秒內自動更新。':'如果付款沒有成功，可以重新付款；訂單成立 30 分鐘內未完成付款會自動取消。'):''}</p>${r.mode==='stage'?'<p class="muted">綠界測試環境：不會真的扣款。</p>':''}<ul class="order-status-items">${statusItems(o)}<li class="summary-total"><span>總額 · ${esc(paymentNames[o.payment]||o.payment)}</span><strong>${money(o.total)}</strong></li></ul>${waiting?'<button class="primary-button" type="button" id="repay">重新付款</button>':''}${paid&&o.canCancel?`<p class="order-cancel"><button class="secondary-button" type="button" id="cancel-order">取消訂單並退款</button><small>咖啡開始烘焙前可以取消，會全額退款到原信用卡。</small></p>`:paid&&o.cancelNote?`<p class="order-cancel muted"><small>${esc(o.cancelNote)}</small></p>`:''}<a class="text-link" href="shop.html">繼續逛逛 ↗</a></div>`;
  const stop=document.getElementById('cancel-order');if(stop)stop.onclick=async()=>{if(!window.confirm(window.CoffeeI18n?.lang==='en'?`Cancel order ${o.id}?
A full refund of ${money(o.total)} will go back to the card you paid with. This cannot be undone.`:`確定要取消訂單 ${o.id} 嗎？
將全額退款 ${money(o.total)} 到你付款的信用卡，取消後無法復原。`))return;stop.disabled=true;stop.textContent='取消中…';try{await window.CoffeeCloud.cancelOrder(id,token);toast('訂單已取消，退款已送出');renderOrderStatus(id,token,99)}catch(e){toast(e.message);stop.disabled=false;stop.textContent='取消訂單並退款'}};
  const again=document.getElementById('repay');if(again)again.onclick=async()=>{again.disabled=true;again.textContent='前往付款頁面…';try{window.CoffeeCloud.goPay((await window.CoffeeCloud.repay(id,token)).payment)}catch(e){toast(e.message);again.disabled=false;again.textContent='重新付款'}};
  if(waiting&&tries<6)setTimeout(()=>{if(new URLSearchParams(location.search).get('order')===id)renderOrderStatus(id,token,tries+1)},4000)}
 function syncChrome(){const s=view();document.querySelectorAll('.cart-count').forEach(n=>n.textContent=S.cartDetails(s).count);document.querySelectorAll('.store-brand').forEach(n=>n.textContent=s.settings.shopName);document.querySelectorAll('.support-email').forEach(a=>{a.textContent=s.settings.supportEmail;a.href='mailto:'+encodeURIComponent(s.settings.supportEmail)})}
 const page=document.body.dataset.page;
 try{const saved=localStorage.getItem('encounter-site-theme');if(['terra','forest','cobalt','nocturne'].includes(saved))root.dataset.theme=saved}catch(_){}
 if(page==='catalog')renderCatalog();if(page==='product')renderProduct();if(page==='treats')renderTreats();if(page==='subscribe')renderSubscribe();if(page==='checkout')renderCheckout();if(page==='lookup')renderLookup();function renderHome(){const active=view().products.filter(p=>p.active),selected=[];['floral','sweet','cocoa'].forEach(flavor=>{const p=active.find(p=>p.flavor===flavor&&!selected.includes(p));if(p)selected.push(p)});for(const p of active){if(selected.length>=3)break;if(!selected.includes(p))selected.push(p)}document.querySelector('#products .coffee-grid').innerHTML=selected.map(p=>coffeeCard(p,true)).join('');const treatGrid=document.querySelector('.treat-home-grid');if(treatGrid)treatGrid.innerHTML=view().treats.filter(t=>t.active).slice(0,3).map(treatCard).join('');let all=document.getElementById('home-all-coffees');if(!all){all=document.createElement('a');all.id='home-all-coffees';all.href='shop.html';all.className='text-link';document.querySelector('.collection-controls').insertAdjacentElement('afterend',all)}all.textContent='瀏覽全部 '+active.length+' 款熟豆 ↗';window.dispatchEvent(new CustomEvent('coffee:featuredChanged'))}if(page==='home')renderHome();
 syncChrome();window.addEventListener('coffee:change',()=>{syncChrome();if(page==='catalog')renderCatalog();if(page==='product')renderProduct();if(page==='treats')renderTreats();if(page==='home')renderHome();if(page==='checkout'){const form=document.getElementById('checkout-form'),saved=form?Object.fromEntries(new FormData(form)):null;if(form){renderCheckout();if(saved)Object.entries(saved).forEach(([k,v])=>{const el=document.getElementById('checkout-form').elements[k];if(el&&el.type!=='checkbox')el.value=v});}}});
 window.addEventListener('coffee:content',()=>{if(page==='subscribe')renderSubscribe()});window.addEventListener('coffee:change',()=>{if(page==='subscribe'&&renderSubscribe.open!==undefined&&renderSubscribe.open!==subsOpen())renderSubscribe()});
 window.CoffeeUI={esc,money,toast,act,renderCatalog,renderProduct,renderTreats,renderSubscribe,renderCheckout};
